mapper.select:
SELECT o.id, o.no, o.brand, o.product_line, o.order_date, o.status, COALESCE(o.total_qty, 0) AS total_qty, o.currency,
       (SELECT COALESCE(SUM(i.amount), 0) FROM ord_order_item i WHERE i.order_id = o.id) AS sales_amount
FROM ord_order o
WHERE o.status IN ('APPROVED', 'RUNNING', 'DONE', 'CLOSED') AND o.order_date BETWEEN #{from} AND #{to}

  AND o.product_line = #{productLine}
  AND (o.create_by = #{scope.userId} OR o.sales_id = #{scope.userId} OR o.merch_id = #{scope.userId})

      AND (o.no ILIKE #{keyword} OR o.customer_order_no ILIKE #{keyword} OR o.brand ILIKE #{keyword})

ORDER BY o.order_date DESC, o.id DESC
LIMIT #{limit}
